<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Chatbot';$errors=[];$current=null;
if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token de respuesta alterado.');$s=db()->prepare('SELECT * FROM chatbot_respuestas WHERE id=?');$s->execute([$id]);$current=$s->fetch();if(!$current){http_response_code(404);exit('Respuesta no encontrada.');}}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$keywords=clean_text($_POST['palabras_clave']??'',500);$answer=clean_multiline($_POST['respuesta']??'',4000);$priority=filter_input(INPUT_POST,'prioridad',FILTER_VALIDATE_INT)?:0;$active=isset($_POST['activo'])?1:0;if(mb_strlen($keywords)<3)$errors[]='Agrega palabras clave separadas por comas.';if(mb_strlen($answer)<5)$errors[]='Escribe una respuesta.';if(!$errors){if($fa==='create')db()->prepare('INSERT INTO chatbot_respuestas(palabras_clave,respuesta,prioridad,activo)VALUES(?,?,?,?)')->execute([$keywords,$answer,$priority,$active]);else{$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('UPDATE chatbot_respuestas SET palabras_clave=?,respuesta=?,prioridad=?,activo=? WHERE id=?')->execute([$keywords,$answer,$priority,$active,$id]);}flash('success','Respuesta del chatbot guardada.');redirect('admin/chatbot.php');}}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('DELETE FROM chatbot_respuestas WHERE id=?')->execute([$id]);flash('success','Respuesta eliminada.');redirect('admin/chatbot.php');}}
$items=db()->query('SELECT * FROM chatbot_respuestas ORDER BY prioridad DESC,id DESC')->fetchAll();require dirname(__DIR__).'/includes/admin_header.php';
?>
<div class="panel-heading"><div><h1>Respuestas del chatbot</h1><p>Base de conocimiento por palabras clave.</p></div></div><div class="grid-2"><form class="card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$current?'update':'create'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><h2><?=$current?'Editar respuesta':'Nueva respuesta'?></h2><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="field"><label>Palabras clave</label><input name="palabras_clave" value="<?=e($current['palabras_clave']??'')?>" placeholder="precio,costo,cuesta" required></div><div class="field"><label>Respuesta</label><textarea name="respuesta" required><?=e($current['respuesta']??'')?></textarea></div><div class="field"><label>Prioridad</label><input type="number" name="prioridad" value="<?=e(isset($current['prioridad'])?(string)$current['prioridad']:'0')?>"></div><label><input type="checkbox" name="activo" style="width:auto" <?=!$current||$current['activo']?'checked':''?>> Activa</label><div class="actions"><button class="btn">Guardar</button><?php if($current):?><a class="btn btn-light" href="<?=url('admin/chatbot.php')?>">Cancelar</a><?php endif;?></div></form><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Palabras clave</th><th>Prioridad</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($items as$it):?><tr><td><strong><?=e($it['palabras_clave'])?></strong><br><small><?=e(mb_strimwidth($it['respuesta'],0,100,'…'))?></small></td><td><?=(int)$it['prioridad']?></td><td><?=$it['activo']?'Activa':'Inactiva'?></td><td class="table-actions"><a class="btn btn-small btn-light" href="<?=url('admin/chatbot.php?t='.encode_id((int)$it['id']))?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar esta respuesta?">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>
